const resourceValidatedAt = `-- name: ResourceValidatedAt :one
SELECT transaction_timestamp()::pg_catalog.timestamptz AS validated_at
`

func (q *Queries) ResourceValidatedAt(ctx context.Context) (time.Time, error) {
	row := q.db.QueryRow(ctx, resourceValidatedAt)
	var validated_at time.Time
	err := row.Scan(&validated_at)
	return validated_at, err
}

const resourceWorkAttempts = `-- name: ResourceWorkAttempts :many
SELECT execution_id,max(attempts)::int AS attempts FROM resource_work WHERE execution_id=ANY($1::text[]) GROUP BY 1
`

type ResourceWorkAttemptsRow struct {
	ExecutionID string
	Attempts    int32
}

func (q *Queries) ResourceWorkAttempts(ctx context.Context, ids []string) ([]ResourceWorkAttemptsRow, error) {
	rows, err := q.db.Query(ctx, resourceWorkAttempts, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ResourceWorkAttemptsRow
	for rows.Next() {
		var i ResourceWorkAttemptsRow
		if err := rows.Scan(&i.ExecutionID, &i.Attempts); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

